[
  {
    "question": "Sort these numbers in ascending order: 42, 7, 19, 3, 88, 25.",
    "answer": "3, 7, 19, 25, 42, 88"
  },
  {
    "question": "Reverse the string 'pineapple'.",
    "answer": "elppaenip"
  },
  {
    "question": "Alphabetize these words: mango, apple, kiwi, banana, cherry.",
    "answer": "apple, banana, cherry, kiwi, mango"
  },
  {
    "question": "Convert 'hello world' to all uppercase letters.",
    "answer": "HELLO WORLD"
  },
  {
    "question": "Sort these numbers in descending order: 15, 2, 99, 47, 8.",
    "answer": "99, 47, 15, 8, 2"
  },
  {
    "question": "Remove all the vowels from the word 'computer'.",
    "answer": "cmptr"
  },
  {
    "question": "Convert 'MIXED CASE TEXT' to all lowercase letters.",
    "answer": "mixed case text"
  },
  {
    "question": "Sort these words by length, shortest first: elephant, cat, dog, hippopotamus, ox.",
    "answer": "ox, cat, dog, elephant, hippopotamus"
  },
  {
    "question": "Reverse the order of words in this sentence: 'the quick brown fox'.",
    "answer": "fox brown quick the"
  },
  {
    "question": "Replace every space in 'a b c d' with a hyphen.",
    "answer": "a-b-c-d"
  },
  {
    "question": "Sort these letters alphabetically: t, a, m, k, b.",
    "answer": "a, b, k, m, t"
  },
  {
    "question": "Capitalize the first letter of each word: 'welcome to the show'.",
    "answer": "Welcome To The Show"
  },
  {
    "question": "Remove all digits from the string 'abc123def456'.",
    "answer": "abcdef"
  },
  {
    "question": "Sort these names alphabetically by last name: John Smith, Amy Adams, Carl Baker.",
    "answer": "Amy Adams, Carl Baker, John Smith"
  },
  {
    "question": "Swap the case of every letter in 'AbCdEf'.",
    "answer": "aBcDeF"
  },
  {
    "question": "Sort these numbers and then list only the even ones: 9, 4, 7, 12, 5, 8.",
    "answer": "4, 8, 12"
  },
  {
    "question": "Repeat the string 'ha' three times with no spaces.",
    "answer": "hahaha"
  },
  {
    "question": "Sort these decimal numbers from smallest to largest: 0.5, 0.05, 0.55, 0.005.",
    "answer": "0.005, 0.05, 0.5, 0.55"
  },
  {
    "question": "Take the first three letters of each word and join them: 'running jumping swimming'.",
    "answer": "runjumswi"
  },
  {
    "question": "Sort the characters in 'string' alphabetically.",
    "answer": "ginrst"
  }
]
